@Component({
  selector: 'app-employee-search',
  imports: [ReactiveFormsModule],
  template: `
    <input [formControl]="term" placeholder="Search employees">
    @for (e of hits(); track e.id) { <li>{{ e.name }}</li> }
  `,
})
export class EmployeeSearchComponent {
  private http = inject(HttpClient);
  term = new FormControl('', { nonNullable: true });

  hits = toSignal(
    this.term.valueChanges.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(q => this.http
        .get<Employee[]>('/api/employees', { params: { q } })
        .pipe(catchError(() => of([])))),
    ),
    { initialValue: [] as Employee[] },
  );
}

export const TenderActions = createActionGroup({
  source: 'Tenders',
  events: {
    'Load': emptyProps(),
    'Load Success': props<{ tenders: Tender[] }>(),
    'Load Failure': props<{ error: string }>(),
  },
});

export const loadTenders = createEffect(
  (actions$ = inject(Actions), api = inject(TenderApi)) =>
    actions$.pipe(
      ofType(TenderActions.load),
      switchMap(() => api.list().pipe(
        map(tenders => TenderActions.loadSuccess({ tenders })),
        catchError(e => of(TenderActions.loadFailure({ error: e.message }))),
      )),
    ),
  { functional: true },
);
export const selectOpenTenders = createSelector(
  selectAllTenders,
  tenders => tenders.filter(t => t.status === 'open'),
);

