@Component({
  selector: 'app-dashboard',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [RowComponent, HeavyChartComponent],
  template: `
    @for (row of rows(); track row.id) { <app-row [row]="row" /> }
    @defer (on viewport) {
      <app-heavy-chart [data]="rows()" />
    } @placeholder {
      <div class="chart-skeleton"></div>
    }
  `,
})
export class DashboardComponent {
  rows = input.required<Row[]>();
}

export const authGuard: CanActivateFn = (_route, state) => {
  const auth = inject(AuthService);
  return auth.isLoggedIn()
    || inject(Router).createUrlTree(['/login'], { queryParams: { returnUrl: state.url } });
};

export const roleGuard = (role: string): CanMatchFn => () =>
  inject(AuthService).hasRole(role) || inject(Router).createUrlTree(['/forbidden']);

export const unsavedChangesGuard: CanDeactivateFn<{ isDirty(): boolean }> =
  (cmp) => !cmp.isDirty() || confirm('Discard unsaved changes?');

export const routes: Routes = [
  { path: 'payroll',
    canMatch: [roleGuard('payroll-admin')],
    canActivate: [authGuard],
    loadChildren: () => import('./payroll/routes').then(m => m.PAYROLL_ROUTES) },
  { path: 'employees/:id/edit',
    component: EmployeeEditComponent,
    canDeactivate: [unsavedChangesGuard] },
];

type FieldConfig = { key: string; type: 'text' | 'number' | 'date'; required?: boolean };

export function buildForm(fb: NonNullableFormBuilder, fields: FieldConfig[]) {
  const controls: Record<string, FormControl<string>> = {};
  for (const f of fields) {
    controls[f.key] = fb.control('', f.required ? [Validators.required] : []);
  }
  return fb.group(controls);
}

export const noWeekend: ValidatorFn = (c: AbstractControl) => {
  const day = new Date(c.value).getDay();
  return day === 0 || day === 6 ? { weekend: true } : null;
};

export function uniqueEmail(api: EmployeeApi): AsyncValidatorFn {
  return (c) => timer(300).pipe(
    switchMap(() => api.emailExists(c.value)),
    map(exists => (exists ? { emailTaken: true } : null)),
  );
}

@Directive({ selector: '[appHasRole]' })
export class HasRoleDirective {
  private tpl = inject(TemplateRef<unknown>);
  private vcr = inject(ViewContainerRef);
  private auth = inject(AuthService);
  appHasRole = input.required<string>();

  constructor() {
    effect(() => {
      this.vcr.clear();
      if (this.auth.hasRole(this.appHasRole())) this.vcr.createEmbeddedView(this.tpl);
    });
  }
}

@Pipe({ name: 'eur' }) // pure by default
export class EurPipe implements PipeTransform {
  private fmt = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' });
  transform(v: number | null): string {
    return v == null ? '' : this.fmt.format(v);
  }
}

